===== predicate-witness
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "programPredicateDigest",
  "matchingFactIds",
  "coverageIds",
  "countLimit",
  "childPredicateIds"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "programPredicateDigest": {
   "$ref": "#/$defs/Hash"
  },
  "matchingFactIds": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "string",
    "pattern": "^fact2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "x-opensip-order": "canonical-set"
  },
  "coverageIds": {
   "type": "array",
   "maxItems": 100000,
   "uniqueItems": true,
   "items": {
    "type": "string",
    "pattern": "^coverage2:[0-9a-f]{64}(?![\\s\\S])"
   },
   "x-opensip-order": "canonical-set"
  },
  "countLimit": {
   "oneOf": [
    {
     "type": "null"
    },
    {
     "$ref": "#/$defs/U64"
    }
   ]
  },
  "childPredicateIds": {
   "type": "array",
   "maxItems": 1024,
   "uniqueItems": true,
   "items": {
    "$ref": "#/$defs/Text"
   },
   "x-opensip-order": "canonical-set"
  }
 }
}
===== finding
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "fingerprint",
  "ruleClosure",
  "subjectId",
  "messageCode",
  "parameterDigest",
  "severity",
  "evidenceRefs"
 ],
