   "pattern": "^finding-key2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "ruleClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "subjectId": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "messageCode": {
   "type": "string",
   "minLength": 1,
   "maxLength": 4096
  },
  "parameterDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])"
  },
  "severity": {
   "type": "string",
   "enum": [
    "note",
    "warning",
    "error"
   ]
  },
  "evidenceRefs": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "$ref": "#/$defs/FindingEvidenceRef"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  }
 }
}
===== execution-plan
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "planId",
  "stages"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "planId": {
   "type": "string",
   "pattern": "^plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "stages": {
   "type": "array",
   "maxItems": 1024,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "ordinal",
     "stageSpecDigest",
     "requires",
     "outputDomains"
    ],
    "properties": {
     "ordinal": {
      "type": "integer",
      "minimum": 0,
      "maximum": 18446744073709551615
     },
     "stageSpecDigest": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}(?![\\s\\S])"
     },
     "requires": {
      "type": "array",
      "maxItems": 1024,
      "items": {
       "type": "integer",
       "minimum": 0,
       "maximum": 18446744073709551615
      },
      "uniqueItems": true,
      "x-opensip-order": "numeric"
     },
     "outputDomains": {
      "type": "array",
      "maxItems": 128,
      "items": {
       "type": "string",
       "minLength": 1,
       "maxLength": 4096
      },
      "uniqueItems": true,
      "x-opensip-order": "canonical-set"
     }
    }
   },
   "uniqueItems": true,
   "x-opensip-order": "ordinal"
  }
 }
}
