===== proof-bundle
{
 "type": "object",
 "additionalProperties": false,
 "required": [
  "schemaVersion",
  "planId",
  "executionPlanId",
  "evaluatorClosure",
  "ruleProgramDigest",
  "evaluationInputRefs",
  "predicateProofs",
  "findingIds",
  "verdict"
 ],
 "properties": {
  "schemaVersion": {
   "const": 2
  },
  "planId": {
   "type": "string",
   "pattern": "^plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "executionPlanId": {
   "type": "string",
   "pattern": "^exec-plan2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "evaluatorClosure": {
   "type": "string",
   "pattern": "^closure2:[0-9a-f]{64}(?![\\s\\S])"
  },
  "ruleProgramDigest": {
   "type": "string",
   "pattern": "^[0-9a-f]{64}(?![\\s\\S])"
  },
  "evaluationInputRefs": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "$ref": "#/$defs/ProofInputRef"
   },
   "uniqueItems": true,
   "x-opensip-order": "canonical-set"
  },
  "predicateProofs": {
   "type": "array",
   "maxItems": 100000,
   "items": {
    "type": "object",
    "additionalProperties": false,
    "required": [
     "ruleId",
     "subjectId",
     "predicateId",
     "operation",
     "inputRefs",
     "scopeIds",
     "value",
     "witnessDigest"
    ],
    "properties": {
