      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "subjectId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "predicateId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 4096
     },
     "operation": {
      "type": "string",
